    // Calculate vectors
    vec2 v0 = c - a;
    vec2 v1 = b - a;
    vec2 v2 = p - a;

    // Calculate dot products
    double dot00 = v0.x * v0.x + v0.y * v0.y;
    double dot01 = v0.x * v1.x + v0.y * v1.y;
    double dot11 = v1.x * v1.x + v1.y * v1.y;
    double dot20 = v2.x * v0.x + v2.y * v0.y;
    double dot21 = v2.x * v1.x + v2.y * v1.y;

    // Calculate barycentric coordinates
    double denom = dot00 * dot11 - dot01 * dot01;
    if (denom < 1e-12 && denom > -1e-12) {
        return vec3(0.0, 0.0, 0.0);
    }

    double invDenom = 1.0 / denom;
    double u = (dot11 * dot20 - dot01 * dot21) * invDenom;
    double v = (dot00 * dot21 - dot01 * dot20) * invDenom;
    double w = 1.0 - u - v;

    return vec3(u, v, w);
}

